// GIVEN. Do not edit this file.
using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Interactivity;
using Avalonia.Threading;

namespace DatabasesLab;

/// <summary>Thrown when the check looks for a control by x:Name and it is not there yet.</summary>
public class NotFinishedException : Exception
{
    public NotFinishedException(string message) : base(message)
    {
    }
}

/// <summary>
/// Opens a MainWindow with no screen, types into its boxes, clicks its buttons,
/// and reads what it shows. Every control is found by its x:Name.
/// </summary>
public class WindowDriver
{
    private static bool started;
    private readonly MainWindow window;

    private WindowDriver(MainWindow window)
    {
        this.window = window;
    }

    /// <summary>Opens a new window on the given database file.</summary>
    public static WindowDriver Open(string databasePath)
    {
        if (!started)
        {
            AppBuilder.Configure<App>()
                .UseHeadless(new AvaloniaHeadlessPlatformOptions { UseHeadlessDrawing = true })
                .SetupWithoutStarting();
            started = true;
        }

        MainWindow window = new MainWindow(databasePath);
        window.Show();
        Dispatcher.UIThread.RunJobs();
        return new WindowDriver(window);
    }

    /// <summary>Closes the window.</summary>
    public void Close()
    {
        window.Close();
        Dispatcher.UIThread.RunJobs();
    }

    /// <summary>Replaces the text in a TextBox, the way typing would.</summary>
    public void Type(string boxName, string text)
    {
        Find<TextBox>(boxName).Text = text;
        Dispatcher.UIThread.RunJobs();
    }

    /// <summary>What a TextBox holds right now.</summary>
    public string BoxText(string boxName)
    {
        return Find<TextBox>(boxName).Text ?? "";
    }

    /// <summary>What a TextBlock shows right now.</summary>
    public string Text(string blockName)
    {
        return Find<TextBlock>(blockName).Text ?? "";
    }

    /// <summary>Clicks a button.</summary>
    public void Click(string buttonName)
    {
        Find<Button>(buttonName).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        Dispatcher.UIThread.RunJobs();
    }

    /// <summary>The text of every row in ItemsList, top to bottom.</summary>
    public List<string> ListedItems()
    {
        List<string> rows = new List<string>();
        foreach (object? item in Find<ListBox>("ItemsList").Items)
        {
            rows.Add(item?.ToString() ?? "");
        }
        return rows;
    }

    /// <summary>Selects the row in ItemsList that starts with #number.</summary>
    public void Select(int number)
    {
        ListBox list = Find<ListBox>("ItemsList");
        int index = -1;
        int i = 0;
        while (index == -1 && i < list.ItemCount)
        {
            if ((list.Items[i]?.ToString() ?? "").StartsWith("#" + number + " "))
            {
                index = i;
            }
            i++;
        }

        if (index == -1)
        {
            throw new InvalidOperationException("ItemsList has no row for #" + number + ".");
        }

        list.SelectedIndex = index;
        Dispatcher.UIThread.RunJobs();
    }

    /// <summary>Clears the selection in ItemsList.</summary>
    public void SelectNothing()
    {
        Find<ListBox>("ItemsList").SelectedIndex = -1;
        Dispatcher.UIThread.RunJobs();
    }

    private T Find<T>(string name) where T : Control
    {
        T? control = window.FindControl<T>(name);
        if (control == null)
        {
            throw new NotFinishedException("No " + typeof(T).Name + " named " + name + ".");
        }
        return control;
    }
}
